INSERT IGNORE INTO motor(kode,nama,merek,tipe,tahun,deskripsi) VALUES('M001','Honda BeAT','Honda','Matic',2023,'Honda BeAT matic tahun 2023'),('M002','Vario 125','Honda','Vario 125',2023,'Honda Vario 125 tahun 2023'),('M003','Scoopy','Honda','Scoopy',2023,'Honda Scoopy tahun 2023');
INSERT IGNORE INTO gejala(kode,nama,deskripsi) VALUES('G001','Mesin sulit dihidupkan','Mesin perlu distarter berulang kali sebelum hidup.'),('G002','Mesin sering mati','Mesin mati mendadak saat langsam atau digunakan.'),('G003','Suara mesin kasar','Mesin mengeluarkan suara tidak normal atau kasar.'),('G004','Motor kehilangan tenaga','Akselerasi lemah dan tenaga mesin berkurang.'),('G005','Asap knalpot berlebihan','Asap knalpot tampak lebih banyak dari kondisi normal.'),('G006','Mesin cepat panas','Suhu mesin naik berlebihan dalam pemakaian normal.');
INSERT IGNORE INTO kerusakan(kode,nama,deskripsi,status) VALUES('K001','Kerusakan Busi','Busi aus, kotor, atau percikan api tidak optimal.','aktif'),('K002','Kerusakan Injektor','Suplai bahan bakar dari injektor terganggu.','aktif'),('K003','Sistem Pendingin Bermasalah','Sistem pendinginan tidak menjaga suhu mesin pada batas normal.','aktif');
INSERT INTO solusi(kerusakan_id,deskripsi) SELECT id,'Periksa kondisi busi, bersihkan busi, dan ganti jika elektroda rusak.' FROM kerusakan k WHERE kode='K001' AND NOT EXISTS(SELECT 1 FROM solusi WHERE kerusakan_id=k.id);
INSERT INTO solusi(kerusakan_id,deskripsi) SELECT id,'Periksa dan bersihkan injektor serta pastikan aliran bahan bakar dan tekanan pompa normal.' FROM kerusakan k WHERE kode='K002' AND NOT EXISTS(SELECT 1 FROM solusi WHERE kerusakan_id=k.id);
INSERT INTO solusi(kerusakan_id,deskripsi) SELECT id,'Periksa cairan pendingin, kipas, radiator, dan jalur sirkulasi pendingin.' FROM kerusakan k WHERE kode='K003' AND NOT EXISTS(SELECT 1 FROM solusi WHERE kerusakan_id=k.id);
INSERT INTO aturan(kode,kerusakan_id) SELECT 'R001',id FROM kerusakan WHERE kode='K001' AND NOT EXISTS(SELECT 1 FROM aturan WHERE kode='R001');
INSERT INTO aturan(kode,kerusakan_id) SELECT 'R002',id FROM kerusakan WHERE kode='K002' AND NOT EXISTS(SELECT 1 FROM aturan WHERE kode='R002');
INSERT INTO aturan(kode,kerusakan_id) SELECT 'R003',id FROM kerusakan WHERE kode='K003' AND NOT EXISTS(SELECT 1 FROM aturan WHERE kode='R003');
INSERT IGNORE INTO aturan_detail(aturan_id,gejala_id) SELECT a.id,g.id FROM aturan a JOIN gejala g ON g.kode IN ('G001','G002') WHERE a.kode='R001';
INSERT IGNORE INTO aturan_detail(aturan_id,gejala_id) SELECT a.id,g.id FROM aturan a JOIN gejala g ON g.kode IN ('G003','G004') WHERE a.kode='R002';
INSERT IGNORE INTO aturan_detail(aturan_id,gejala_id) SELECT a.id,g.id FROM aturan a JOIN gejala g ON g.kode IN ('G005','G006') WHERE a.kode='R003';
